package com.college.attendance.controller;
import com.college.attendance.dto.MarkAttendanceRequest; import com.college.attendance.dto.VerificationAttemptRequest; import com.college.attendance.dto.VerificationAttemptResponse; import com.college.attendance.entity.*; import com.college.attendance.repo.*; import com.college.attendance.service.AttendanceVerificationService; import org.springframework.http.HttpStatus; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/student") public class StudentController {
 private final UserRepository users; private final StudentRepository students; private final AttendanceSessionRepository sessions; private final AttendanceRecordRepository records; private final AssignmentRepository assignments; private final SubjectRepository subjects; private final AttendanceVerificationService verification;
 public StudentController(UserRepository u,StudentRepository s,AttendanceSessionRepository as,AttendanceRecordRepository ar,AssignmentRepository a,SubjectRepository sub,AttendanceVerificationService verification){users=u;students=s;sessions=as;records=ar;assignments=a;subjects=sub;this.verification=verification;}
 private Student me(){String e=SecurityContextHolder.getContext().getAuthentication().getName(); return students.findByUser(users.findByEmail(e).orElseThrow()).orElseThrow();}
 @GetMapping("/profile") public Student profile(){return me();}
 @GetMapping("/attendance") public List<AttendanceRecord> attendance(){return records.findByStudentOrderByMarkedAtDesc(me());}
 @GetMapping("/active-session") public Object active(){return sessions.findFirstBySectionAndActiveTrue(me().getSection()).filter(s -> s.getEndTime().isAfter(LocalDateTime.now())).orElse(null);}
 @PostMapping("/attendance/verification-attempt") public VerificationAttemptResponse startVerification(@RequestBody VerificationAttemptRequest request){if(request.getSessionId()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"sessionId is required");return verification.start(me(),request.getSessionId());}
 @PostMapping("/attendance/mark") public Object mark(@RequestBody MarkAttendanceRequest ignored){throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Attendance is recorded only after server-side face verification");}
 @GetMapping("/assignments") public List<Assignment> assignments(){return assignments.findBySubjectIn(subjects.findBySection(me().getSection()));}
}
